package gnb

import "encoding/base64"

const (
	sourceToTargetSynthetic = ""

	targetToSourceSynthetic = "NWk0qgjOlkLlURQfOk5jgAaO/elU+z3Zm2iggUSYOJ7uTJpJUgWqP0yqayF7VUxjm/y80IwOmsodOw1sM2a6G1rmdY3e9MpCUJ4+mRt7Xd5FM1F1etqSq/9GmgA4EpqDB8thLNkOor++kfOkAaqjNmbkPfIy9HAJV5dnD1LLWurYZXwmQdF6ZHVVe73mSIvU3+d1TOX75r8G2C/WlQxeaw=="

	ranStatusTransferSynthetic = "FcNRN7174Hx/WN+J6NLVz0H4F13zmfVh"
)

func mustDecode(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic("gnb: decode handover container fixture: " + err.Error())
	}

	return b
}

var (
	sourceToTargetContainer    = mustDecode(sourceToTargetSynthetic)
	targetToSourceContainer    = mustDecode(targetToSourceSynthetic)
	ranStatusTransferContainer = mustDecode(ranStatusTransferSynthetic)
)

func SourceToTargetContainer() []byte {
	return sourceToTargetContainer
}

func TargetToSourceContainer() []byte {
	return targetToSourceContainer
}

func RANStatusTransferContainer() []byte {
	return ranStatusTransferContainer
}
